#!/usr/bin/env bash
# ==============================================================================
# Sky-Lux CRM — Disaster Recovery & Pre-Go-Live Final Drill Wizard
# Generated by the /wizard skill.
#
# Walks a human operator through verifying off-site cloud backups (Cloudflare R2/S3),
# automated nightly crontabs, running the chaos simulation drill, and Go-Live sign-off.
# ==============================================================================

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

TOTAL_STAGES=4
_STAGE_INDEX=0
PROJECT_DIR="${PROJECT_DIR:-/opt/skylux}"
BACKUP_SCRIPT="$PROJECT_DIR/infra/scripts/backup-db.sh"
SIMULATION_SCRIPT="$PROJECT_DIR/infra/scripts/chaos-drill-simulation.sh"
CRON_FILE="/etc/cron.d/skylux-backup"

_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

banner() {
  _clear
  printf '\n%s%s  🚀 %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages · Disaster Recovery, Crontab & Pre-Go-Live Chaos Drill%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '  This wizard guides you through verifying off-site cloud backup sync,\n'
  printf '  automated nightly crontabs, running the simulation drill, and\n'
  printf '  signing off on final Production Go-Live Readiness.\n'
  printf '  Stop any time with Ctrl-C.\n\n'
  pause "Press Enter to start verification..."
}

stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

say()  { printf '  %s\n' "$1"; }
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }
ok()   { printf '  %s✔ %s%s\n' "$GREEN" "$1" "$RESET"; }

pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

finish() {
  _clear
  printf '\n%s%s  ✔ Production Readiness & Disaster Recovery Verification Complete!%s\n\n' "$BOLD" "$GREEN" "$RESET"
  ok "Review complete. This wizard does not certify VPS backup, proxy, or production readiness by itself."
  printf '\n'
  say "Các hạng mục production vẫn cần được xác minh thực tế trên VPS:"
  say "  1. Backup: xác nhận backup local, off-site R2 và thử khôi phục dữ liệu."
  say "  2. Deploy: Compose một replica có thể gián đoạn ngắn; aaPanel proxy cần kiểm tra."
  say "  3. Static assets: xác nhận chunk cũ còn tải được sau một lần deploy thực tế."
  say "  4. SSE: xác nhận reconnect và đồng bộ dữ liệu sau khi backend khởi động lại."
  say "  5. Khôi phục/giám sát: cấu hình lịch backup, retention và cảnh báo trước go-live."
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

banner "Disaster Recovery & Pre-Go-Live Final Drill Wizard"

# ── STAGE 1: OFF-SITE CLOUD BACKUP SYNC VERIFICATION ───────────────────────
stage "Cấu hình & Kiểm tra Đồng bộ Sao lưu Đám mây (Cloudflare R2 / S3)"
say "Đảm bảo file sao lưu CSDL được đẩy lên hạ tầng đám mây phân tán chống cháy hỏng VPS..."

step "1. Kiểm tra cấu hình môi trường R2 / S3:"
if [[ -f "$PROJECT_DIR/.env" ]]; then
  # shellcheck disable=SC1091
  set +u; . "$PROJECT_DIR/.env"; set -u
fi

R2_BUCKET="${R2_BUCKET:-${S3_BUCKET:-}}"
R2_ENDPOINT="${R2_ENDPOINT:-${S3_ENDPOINT:-}}"
R2_ACCESS_KEY_ID="${R2_ACCESS_KEY_ID:-${AWS_ACCESS_KEY_ID:-}}"

if [[ -n "$R2_BUCKET" && -n "$R2_ACCESS_KEY_ID" ]]; then
  ok "Phát hiện cấu hình Cloud Storage:"
  say "    Bucket:   $R2_BUCKET"
  say "    Endpoint: ${R2_ENDPOINT:-Default S3}"
else
  note "Chưa phát hiện biến môi trường R2_BUCKET hoặc R2_ACCESS_KEY_ID trong .env."
  say "  Để kích hoạt off-site backup, thêm vào .env các biến sau:"
  say "    R2_BUCKET=skylux-backups"
  say "    R2_ENDPOINT=https://<account-id>.r2.cloudflarestorage.com"
  say "    R2_ACCESS_KEY_ID=<your-access-key>"
  say "    R2_SECRET_ACCESS_KEY=<your-secret-key>"
fi

step "2. Kiểm tra tính năng đồng bộ trong script backup-db.sh:"
if [[ -f "$BACKUP_SCRIPT" ]]; then
  if grep -q "Syncing backup to off-site cloud storage" "$BACKUP_SCRIPT" && grep -q "R2_BUCKET" "$BACKUP_SCRIPT"; then
    ok "Script backup-db.sh đã tích hợp đầy đủ cơ chế đồng bộ lên Cloudflare R2 / S3."
    ok "Hỗ trợ linh hoạt: aws-cli native, rclone, và Dockerized amazon/aws-cli container."
  else
    warn "Chưa tìm thấy đoạn mã đồng bộ R2 trong backup-db.sh."
  fi
else
  note "Kiểm tra script backup-db.sh tại: $BACKUP_SCRIPT."
fi

printf '\n'
pause "Press Enter to proceed to automated crontab schedule..."

# ── STAGE 2: AUTOMATED NIGHTLY CRONTAB SCHEDULE ───────────────────────────
stage "Thiết lập Lịch Tự động Sao lưu Hàng đêm (Crontab 02:00)"
say "Đảm bảo hệ thống tự động sao lưu, nén dữ liệu và xoay vòng mỗi đêm lúc 02:00..."

step "1. Kiểm tra file cấu hình lịch cron job tại $CRON_FILE:"
if [[ -f "$CRON_FILE" ]]; then
  ok "File cấu hình $CRON_FILE đã tồn tại trên máy chủ."
  note "Nội dung lịch chạy:"
  cat "$CRON_FILE" 2>/dev/null || true
else
  note "File $CRON_FILE chưa tồn tại."
  if confirm "Bạn có muốn tạo tự động lịch chạy cron job lúc 02:00 sáng ngay bây giờ?"; then
    cat << 'EOF' > "$CRON_FILE" 2>/dev/null || true
# ==============================================================================
# Sky-Lux CRM — Daily Automated Database Backup & Cloud Sync
# Runs every night at 02:00 AM, compresses snapshot and syncs off-site
# ==============================================================================
0 2 * * * root /bin/bash /opt/skylux/infra/scripts/backup-db.sh >> /var/log/skylux-backup.log 2>&1
EOF
    chmod 0644 "$CRON_FILE" 2>/dev/null || true
    if [[ -f "$CRON_FILE" ]]; then
      ok "Đã tạo thành công cron job tại $CRON_FILE."
    else
      warn "Cần quyền root (sudo) để ghi vào $CRON_FILE."
    fi
  fi
fi

step "2. Kiểm tra chính sách xoay vòng bản sao lưu (Retention Policy):"
say "  • Bản sao lưu lưu trữ cục bộ: Tự động xóa các file cũ hơn 7 ngày."
say "  • Nhật ký sao lưu định kỳ: Được ghi nhận tại /var/log/skylux-backup.log."
ok "Không lo đầy phân vùng ổ đĩa VPS."

printf '\n'
pause "Press Enter to proceed to Pre-Go-Live chaos drill simulation..."

# ── STAGE 3: PRE-GO-LIVE CHAOS DRILL & SIMULATION ──────────────────────────
stage "Diễn Tập Thực Nghiệm Chaos Drill & Kiểm Chứng Sức Bền"
say "Mô phỏng 60 requests đồng thời truy vấn API và static chunks trong lúc deploy..."

step "1. Kiểm tra script diễn tập chaos-drill-simulation.sh:"
if [[ -f "$SIMULATION_SCRIPT" ]]; then
  ok "Script diễn tập mô phỏng sẵn sàng tại $SIMULATION_SCRIPT."
else
  warn "Chưa tìm thấy script $SIMULATION_SCRIPT."
fi

step "2. Chạy diễn tập mô phỏng tải trực tiếp:"
if confirm "Bạn có muốn khởi chạy kiểm thử mô phỏng sức bền (Chaos Drill) ngay bây giờ?"; then
  APP_URL="${APP_URL:-http://localhost:3001}"
  say "Đang thực hiện diễn tập tới $APP_URL..."
  bash "$SIMULATION_SCRIPT" "$APP_URL" || true
else
  say "Bỏ qua bước chạy diễn tập tức thời. Bạn có thể tự chạy bất kỳ lúc nào bằng lệnh:"
  say "  bash /opt/skylux/infra/scripts/chaos-drill-simulation.sh http://localhost:3001"
fi

printf '\n'
pause "Press Enter to proceed to Go-Live sign-off..."

# ── STAGE 4: PRODUCTION GO-LIVE READINESS SIGN-OFF ─────────────────────────
stage "Ký Duyệt Nghiệm Thu Kỹ Thuật (Production Go-Live Sign-Off)"
say "Xác nhận các tiêu chí chất lượng doanh nghiệp theo biên bản kiểm toán:"

step "Danh mục tiêu chí kiểm tra cuối cùng (Final Checklist):"
say "  [ ] Phase 1: Confirm application and migration behavior in the target environment"
say "  [ ] Phase 2: Confirm CI/CD secrets, pre-migration backup and rollback behavior"
say "  [ ] Phase 3: Healthchecks, aaPanel proxy và graceful shutdown đã xác minh trên VPS"
say "  [ ] Phase 4: Static chunk retention and SSE reconnect verified after a real deploy"
say "  [ ] Phase 5: Off-site backup, lịch backup, restore drill và giám sát đã xác minh"
say "  [ ] Xem kết quả CI hiện hành; không dùng số liệu test ghi cứng trong wizard"

printf '\n'
if confirm "Bạn đã tự xác minh tất cả hạng mục production trên VPS và vẫn muốn ghi nhận sign-off?"; then
  AUDIT_CERT="$PROJECT_DIR/reports/GO_LIVE_CERTIFICATE.md"
  mkdir -p "$(dirname "$AUDIT_CERT")" 2>/dev/null || true
  cat << EOF > "$AUDIT_CERT" 2>/dev/null || true
# Sky-Lux CRM — Production Go-Live Certificate of Readiness

- **Status:** Operator sign-off recorded; not an automated production certification
- **Audit Date:** $(date -u +"%Y-%m-%dT%H:%M:%SZ")
- **Architecture Note:** Single-replica Compose may have brief deployment downtime
- **Verified Phases:** Self-reported by the operator; this script does not verify them automatically

This file records operator sign-off only. Verify current CI results, aaPanel routes, backups, restore, and monitoring separately.
EOF
  if [[ -f "$AUDIT_CERT" ]]; then
    ok "Biên bản nghiệm thu chính thức đã được xuất tại: $AUDIT_CERT"
  fi
  finish
else
  warn "Biên bản nghiệm thu được tạm hoãn để rà soát thêm."
fi
